        if(!Files.exists(config))AtomicFiles.write(config,("host: 0.0.0.0\nadvertised-host: localhost\nport: 0\ncode-expiry-seconds: 180\nnetwork-restricted: false\n").getBytes(java.nio.charset.StandardCharsets.UTF_8),true);
        var yaml=YamlConfiguration.loadConfiguration(config.toFile());String configuredBind=yaml.getString("host","0.0.0.0");var bindAddress=java.net.InetAddress.getByName(configuredBind);bind=bindAddress.isLoopbackAddress()||!bindAddress.isAnyLocalAddress()&&java.net.NetworkInterface.getByInetAddress(bindAddress)==null?"0.0.0.0":configuredBind;expiry=yaml.getInt("code-expiry-seconds",180);networkRestricted=yaml.getBoolean("network-restricted",false);int port=yaml.getInt("port",0);if(port<0||port>65535)throw new IllegalArgumentException("Agent port must be 1–65535");
