    public static void forceLocalRecovery(PlugModCore core,String confirmation)throws Exception{
        if(!"UNLINK".equals(confirmation))throw new SecurityException("Explicit console UNLINK confirmation required");Path folder=core.getDataFolder().toPath().resolve("network");Files.createDirectories(folder);String id=UUID.randomUUID().toString();Path marker=folder.resolve("link-confirmed.json");if(Files.exists(marker)){AtomicFiles.backup(marker);try{var data=Protocol.JSON.fromJson(Files.readString(marker),JsonObject.class);if(data!=null&&data.has("backendId"))id=UUID.fromString(data.get("backendId").getAsString()).toString();}catch(RuntimeException corrupt){core.getLogger().warning("Unreadable linked identity backed up; explicit local recovery creates a new backend identity.");}}
        Path state=folder.resolve("network-state.json");AtomicFiles.backup(state);AtomicFiles.write(state,Protocol.JSON.toJson(Map.of("schema",1,"enabled",false,"linked",false,"backendId",id,"proxyId","","credential","","nextCredential","")).getBytes(java.nio.charset.StandardCharsets.UTF_8),true);Files.deleteIfExists(marker);
        for(String name:List.of("agent.p12","agent.password")){Path file=folder.resolve(name);AtomicFiles.backup(file);Files.deleteIfExists(file);}Files.deleteIfExists(folder.resolve("pairing-code.txt"));core.restartNetworkAgentAfterLocalRecovery();core.restoreStandaloneWeb();core.getLogger().info("Network identity and credentials locally revoked; remove the stale proxy record before re-pairing. Module data preserved.");
    }
