    public JsonObject status(){JsonObject result=Protocol.object(Map.of("platform","PAPER","minecraft",runtime.minecraft(),"coreVersion",core.getDescription().getVersion(),"java",Runtime.version().feature(),"api",1,"network",agent==null?Map.of():agent.status(),"preparation",preparation(),"runtimePreparation",Protocol.object(Map.of("prepared",forwardingActive())),"webPort",core.getListeningWebPort()));result.add("capabilities",Protocol.JSON.toJsonTree(List.of("configure-forwarding","forwarding-proof","take-control")));result.add("serverRuntime",Protocol.JSON.toJsonTree(runtime));result.add("setup",setup.deepCopy());result.addProperty("centralControl",centralControl);result.addProperty("startupId",Long.toString(java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime()));result.addProperty("gamePort",Bukkit.getPort());result.addProperty("networkRestricted",networkRestricted);return result;}
    @Override public JsonObject status(JsonObject request){JsonObject result=status();if(request.has("forwardingChallenge")){String challenge=request.get("forwardingChallenge").getAsString();if(!challenge.matches("[A-Za-z0-9_-]{43}"))throw new IllegalArgumentException("Invalid forwarding verification challenge");result.getAsJsonObject("runtimePreparation").addProperty("proof",forwardingActive()?Crypto.mac(startupForwardingSecret,challenge):"");}return result;}
