            catch(Exception failure){if(loading!=null)loading.cancel(false);Throwable cause=Protocol.rootCause(failure);error=Objects.toString(cause.getMessage(),cause.getClass().getSimpleName());core.getLogger().log(java.util.logging.Level.WARNING,"Installed module could not load: "+manifest.id(),failure);}
