        if(!data.has("onlineMode")||!data.get("onlineMode").getAsBoolean())throw new SecurityException("Proxy must authenticate players in online mode");String secret=data.get("forwardingSecret").getAsString();if(secret.length()<8||secret.length()>512||secret.contains("\n"))throw new IllegalArgumentException("Invalid forwarding secret");
        Path paper=Path.of("config/paper-global.yml"),properties=Path.of("server.properties"),spigot=Path.of("spigot.yml");if(!Files.isRegularFile(paper)||!Files.isRegularFile(properties))throw new IllegalStateException("Paper configuration files missing");
        var existing=YamlConfiguration.loadConfiguration(paper.toFile());if(YamlConfiguration.loadConfiguration(spigot.toFile()).getBoolean("settings.bungeecord",false))throw new IllegalArgumentException("Existing BungeeCord forwarding conflicts with Velocity modern forwarding; resolve it explicitly");
        String oldSecret=effectiveSecret();if(existing.getBoolean("proxies.velocity.enabled",false)&&!oldSecret.isBlank()&&!oldSecret.equals(secret))throw new IllegalArgumentException("Backend already uses a different Velocity forwarding secret; review the existing proxy before replacing it");
        existing.set("proxies.velocity.enabled",true);existing.set("proxies.velocity.online-mode",true);if(environment==null||environment.isEmpty())existing.set("proxies.velocity.secret",secret);String yaml=existing.saveToString();var check=new YamlConfiguration();check.loadFromString(yaml);
        String original=Files.readString(properties);String updated=java.util.regex.Pattern.compile("(?m)^online-mode=.*$").matcher(original).find()?original.replaceAll("(?m)^online-mode=.*$","online-mode=false"):original+"\nonline-mode=false\n";
